const item = $input.first().json;
    const body = item.body || item;
    const rawMessage = (body.message || '').trim();
    const channelId = String(body.channel_id || '');
    const msgId = String(body.telegram_msg_id || body.msg_id || '');

    // 1. Extraer metadatos de origen [ORIGIN_ID:<id>|NAME:<name>] si existen
    let originChannelId = channelId;
    let originChannelName = '';
    let cleanMessage = rawMessage;

    const originMatch = rawMessage.match(/\[ORIGIN_ID:([^\|\]]+)(?:\|NAME:([^\]]*))?\]/i);
    if (originMatch) {
      originChannelId = originMatch[1].trim();
      originChannelName = (originMatch[2] || '').trim();
      cleanMessage = rawMessage.replace(/\[ORIGIN_ID:([^\|\]]+)(?:\|NAME:([^\]]*))?\]/gi, '').trim();
    }

    // 2. Mensaje vacío
    if (!cleanMessage) {
      return [{
        json: {
          is_valid: false,
          reason: 'Mensaje vacío',
          status: 'DESCARTADO',
          raw_message: rawMessage,
          channel_id: originChannelId,
          channel_name: originChannelName,
          telegram_msg_id: msgId
        }
      }];
    }

    const upper = cleanMessage.toUpperCase();

    // 3. Verificar acción de trading (BUY, SELL, LONG, SHORT, COMPRA, VENTA)
    const hasAction = /\b(BUY|SELL|COMPRA|COMPRAR|VENTA|VENDER|LONG|SHORT)\b/i.test(upper);
    if (!hasAction) {
      return [{
        json: {
          is_valid: false,
          reason: 'No contiene acción de orden (BUY/SELL/LONG/SHORT/COMPRA/VENTA)',
          status: 'DESCARTADO',
          raw_message: rawMessage,
          channel_id: originChannelId,
          channel_name: originChannelName,
          telegram_msg_id: msgId
        }
      }];
    }

    // 4. Verificar presencia de símbolo financiero o Stop Loss
    // Soporta Forex (EURUSD, EUR/USD), Metales (GOLD, SILVER), Índices (US30, NAS100, SPX500, GER40, DAX) y canales temáticos
    const hasSymbol = /\b(GOLD|SILVER|OIL|WTI|BRENT|US30|DJ30|NAS100|USTEC|SPX500|US500|GER30|GER40|DAX30|DAX40|DAX|XAUUSD|XAGUSD|(?:EUR|USD|GBP|JPY|AUD|NZD|CAD|CHF|XAU|XAG|BTC|ETH)\/?[A-Z]{3})\b/i.test(upper) || /\b(GOLD|XAU|FOREX|US30|NAS)\b/i.
  test(originChannelName.toUpperCase());
    const hasStop = /\b(SL|STOP\s*LOSS|STOP)\b/i.test(upper);

    // Si tiene la palabra BUY/SELL pero NO menciona ningún símbolo ni Stop Loss, es texto no-trading (ej. "BUY our course")
    if (!hasSymbol && !hasStop) {
      return [{
        json: {
          is_valid: false,
          reason: 'Contiene acción pero no menciona símbolo financiero ni Stop Loss',
          status: 'DESCARTADO',
          raw_message: rawMessage,
          channel_id: originChannelId,
          channel_name: originChannelName,
          telegram_msg_id: msgId
        }
      }];
    }

    // 5. Descarte de actualizaciones de trades en curso (TP HIT, SL HIT, BREAKEVEN)
    // REGLA CLAVE: Solo se descarta si NO incluye un Stop Loss de una nueva orden
    const isStrictUpdate = /\b(TP\s*\d*\s*HIT|TAKE\s*PROFIT\s*HIT|SL\s*HIT|STOP\s*LOSS\s*HIT|PIPS\s*GAINED|RUNNING\s*IN\s*PROFIT|SECURE\s*PROFIT|BREAKEVEN|CLOSE\s*HALF|CERRAR\s*MITAD)\b/i.test(upper);

    if (isStrictUpdate && !hasStop) {
      return [{
        json: {
          is_valid: false,
          reason: 'Actualización informativa de trade previo (sin nuevo Stop Loss)',
          status: 'DESCARTADO',
          raw_message: rawMessage,
          channel_id: originChannelId,
          channel_name: originChannelName,
          telegram_msg_id: msgId
        }
      }];
    }

    // Señal candidata aprobada: pasa a Groq para extracción formal
    return [{
      json: {
        is_valid: true,
        raw_message: cleanMessage,
        original_message: rawMessage,
        channel_id: originChannelId,
        channel_name: originChannelName,
        dest_channel_id: channelId,
        telegram_msg_id: msgId
      }
    }];

const prefilter = $('Pre-Filtro').first().json;
    const rawMessage = prefilter.raw_message || '';
    const originalMessage = prefilter.original_message || rawMessage;
    const channelId = prefilter.channel_id || '';
    const channelName = prefilter.channel_name || '';
    const msgId = prefilter.telegram_msg_id || '';

    let parsed = null;
    let parserSource = 'GROQ';

    // 1. Intentar parsear respuesta de Groq
    try {
      const groqResp = $input.first()?.json;
      if (groqResp && groqResp.choices && groqResp.choices[0]?.message?.content) {
        parsed = JSON.parse(groqResp.choices[0].message.content);
      }
    } catch (e) {
      parsed = null;
    }

    // 2. Si Groq falló o no extrajo acción/símbolo, entra el Smart Regex Fallback
    if (!parsed || !parsed.action || !parsed.symbol) {
      const upper = rawMessage.toUpperCase();

      // Extraer acción preservando LONG y SHORT
      const actMatch = upper.match(/\b(BUY|SELL|COMPRA|COMPRAR|VENTA|VENDER|LONG|SHORT)\b/);
      let action = null;
      if (actMatch) {
        const a = actMatch[1];
        if (a === 'COMPRA' || a === 'COMPRAR') action = 'BUY';
        else if (a === 'VENTA' || a === 'VENDER') action = 'SELL';
        else action = a;
      }

      // Extraer símbolo
      let symbol = null;
      const symPatterns = [
        /\b(GOLD|XAUUSD|SILVER|XAGUSD|EURUSD|GBPUSD|USDJPY|USDCAD|AUDUSD|NZDUSD|USDCHF|EURJPY|GBPJPY|US30|NAS100|USTEC|SPX500|GER30|GER40|DAX|OIL|WTI|USOUSD)\b/,
        /\b([A-Z]{6})\b/
      ];
      for (const sp of symPatterns) {
        const sm = upper.match(sp);
        if (sm) {
          symbol = sm[1];
          break;
        }
      }

      // Extraer Stop Loss
      let stopLoss = null;
      const slMatch = upper.match(/(?:SL|STOP\s*LOSS|STOP)\s*[:=\-]?\s*([0-9]+(?:\.[0-9]+)?)/);
      if (slMatch) {
        stopLoss = parseFloat(slMatch[1]);
      }

      // Extraer múltiples Take Profits
      let takeProfits = [];
      const tpMatches = [...upper.matchAll(/(?:TP\s*\d*|TAKE\s*PROFIT\s*\d*|TARGET\s*\d*)\s[:=\-]?\s*([0-9]+(?:\.[0-9]+)?)/g)];
      if (tpMatches.length > 0) {
        for (const m of tpMatches) {
          const val = parseFloat(m[1]);
          if (!isNaN(val) && val > 0 && !takeProfits.includes(val)) {
            takeProfits.push(val);
          }
        }
      }

      let takeProfit = takeProfits.length > 0 ? takeProfits[0] : null;
      if (!takeProfit) {
        const tpMatch = upper.match(/(?:TP1?|TAKE\s*PROFIT|TARGET)\s*[:=\-]?\s*([0-9]+(?:\.[0-9]+)?)/);
        if (tpMatch) {
          takeProfit = parseFloat(tpMatch[1]);
          takeProfits.push(takeProfit);
        }
      }

      // Extraer Entry
      let entry = null;
      const entryMatch = upper.match(/(?:ENTRY|ENTRADA|AT|@|PRICE)?\s*([0-9]+(?:\.[0-9]+)?)\s*(?:SL|STOP)/);
      if (entryMatch) {
        entry = parseFloat(entryMatch[1]);
      }

      if (action && symbol && stopLoss && !isNaN(stopLoss)) {
        parsed = {
          is_signal: true,
          action: action,
          symbol: symbol,
          entry: entry,
          stop_loss: stopLoss,
          take_profit: (!takeProfit || Number.isNaN(takeProfit)) ? 0 : takeProfit,
          take_profits: takeProfits,
          notes: 'Smart Regex Fallback'
        };
        parserSource = 'REGEX_FALLBACK';
      }
    }

    // 3. Validar si se extrajo una orden completa
    if (!parsed || !parsed.is_signal || !parsed.action || !parsed.symbol) {
      return [{
        json: {
          execute: false,
          status: 'DESCARTADO',
          reason: 'No se pudo extraer una orden válida (acción, símbolo y SL requeridos)',
          channel_id: channelId,
          channel_name: channelName,
          telegram_msg_id: msgId,
          raw_message: originalMessage,
          json_extraido: parsed
        }
      }];
    }

    // 4. Normalización de acción
    let action = String(parsed.action).toUpperCase().trim();
    if (action === 'COMPRA' || action === 'COMPRAR') action = 'BUY';
    if (action === 'VENTA' || action === 'VENDER') action = 'SELL';

    const isBuy = (action === 'BUY' || action === 'LONG');
    const isSell = (action === 'SELL' || action === 'SHORT');

    if (!isBuy && !isSell) {
      return [{
        json: {
          execute: false,
          status: 'DESCARTADO',
          reason: `Acción desconocida: ${action}`,
          channel_id: channelId,
          channel_name: channelName,
          telegram_msg_id: msgId,
          raw_message: originalMessage,
          json_extraido: parsed
        }
      }];
    }

    const stopLoss = parseFloat(parsed.stop_loss);
    let takeProfit = parseFloat(parsed.take_profit);
    const entry = parsed.entry ? parseFloat(parsed.entry) : null;

    // Normalizar lista de Take Profits
    let tpList = [];
    if (parsed.take_profits && Array.isArray(parsed.take_profits) && parsed.take_profits.length > 0) {
      tpList = parsed.take_profits.map(Number).filter(v => !isNaN(v) && v > 0);
    } else if (!isNaN(takeProfit) && takeProfit > 0) {
      tpList = [takeProfit];
    }

    // Ordenar TPs: ascendente para compras, descendente para ventas
    if (isBuy) {
      tpList.sort((a, b) => a - b);
    } else if (isSell) {
      tpList.sort((a, b) => b - a);
    }
    if (tpList.length > 0) {
      takeProfit = tpList[0];
    }

    // 🛡️ REGLA 1 INQUEBRANTABLE: Stop Loss Obligatorio
    if (isNaN(stopLoss) || stopLoss <= 0) {
      return [{
        json: {
          execute: false,
          status: 'RECHAZO_RIESGO',
          reason: 'Stop Loss OBLIGATORIO ausente o inválido (<= 0)',
          channel_id: channelId,
          channel_name: channelName,
          telegram_msg_id: msgId,
          raw_message: originalMessage,
          json_extraido: parsed
        }
      }];
    }

    // 🛡️ REGLA 2 INQUEBRANTABLE: Coherencia Matemática
    if (entry && !isNaN(entry) && entry > 0) {
      if (isBuy) {
        if (stopLoss >= entry) {
          return [{
            json: {
              execute: false,
              status: 'RECHAZO_RIESGO',
              reason: `Incoherencia BUY: SL (${stopLoss}) debe ser menor a Entrada (${entry})`,
              channel_id: channelId,
              channel_name: channelName,
              telegram_msg_id: msgId,
              raw_message: originalMessage,
              json_extraido: parsed
            }
          }];
        }
        if (!isNaN(takeProfit) && takeProfit > 0 && takeProfit <= entry) {
          return [{
            json: {
              execute: false,
              status: 'RECHAZO_RIESGO',
              reason: `Incoherencia BUY: TP (${takeProfit}) debe ser mayor a Entrada (${entry})`,
              channel_id: channelId,
              channel_name: channelName,
              telegram_msg_id: msgId,
              raw_message: originalMessage,
              json_extraido: parsed
            }
          }];
        }
      } else if (isSell) {
        if (stopLoss <= entry) {
          return [{
            json: {
              execute: false,
              status: 'RECHAZO_RIESGO',
              reason: `Incoherencia SELL: SL (${stopLoss}) debe ser mayor a Entrada (${entry})`,
              channel_id: channelId,
              channel_name: channelName,
              telegram_msg_id: msgId,
              raw_message: originalMessage,
              json_extraido: parsed
            }
          }];
        }
        if (!isNaN(takeProfit) && takeProfit > 0 && takeProfit >= entry) {
          return [{
            json: {
              execute: false,
              status: 'RECHAZO_RIESGO',
              reason: `Incoherencia SELL: TP (${takeProfit}) debe ser menor a Entrada (${entry})`,
              channel_id: channelId,
              channel_name: channelName,
              telegram_msg_id: msgId,
              raw_message: originalMessage,
              json_extraido: parsed
            }
          }];
        }
      }
    }

    // 🛡️ REGLA 3: Homogeneización de Símbolos Institucionales
    let symbol = String(parsed.symbol).toUpperCase().replace(/[^A-Z0-9]/g, '');
    if (symbol === 'GOLD') symbol = 'XAUUSD';
    if (symbol === 'SILVER') symbol = 'XAGUSD';
    if (symbol === 'OIL' || symbol === 'WTI') symbol = 'USOUSD';
    if (symbol === 'NASDAQ' || symbol === 'NAS100') symbol = 'USTEC';
    if (symbol === 'DOW' || symbol === 'US30') symbol = 'US30';

    // 🛡️ REGLA 4: Comentario MT5 Seguro (máx 31 caracteres)
    let comment = channelName || (channelId ? `Ch:${channelId}` : 'Signal');
    if (comment.length > 31) {
      comment = comment.substring(0, 31);
    }

    return [{
      json: {
        execute: true,
        status: 'ENVIADO_MT5',
        reason: `OK (${parserSource})`,
        channel_id: channelId,
        channel_name: channelName,
        telegram_msg_id: msgId,
        raw_message: originalMessage,
        json_extraido: parsed,
        order: {
          execute: true,
          symbol: symbol,
          action: action,
          entry: entry,
          stop_loss: stopLoss,
          take_profit: (!takeProfit || Number.isNaN(takeProfit)) ? 0 : takeProfit,
          take_profits: tpList,
          lot: 0.01,
          channel_id: channelId,
          channel_name: channelName,
          comment: comment,
          order_type: entry ? 'PENDING' : 'MARKET',
          reason: `OK (${parserSource})`
        }
      }
    }];

parameters.jsonBody:
={
  "model": "qwen/qwen3.8-27b",
  "temperature": 0.1,
  "max_tokens": 500,
  "response_format": {
    "type": "json_object"
  },
  "messages": [
    {
      "role": "system",
      "content": "You are a specialized forex trading signal parser. Extract signal details into strict JSON with keys: is_signal (boolean), action (BUY, SELL, LONG, SHORT or null), symbol (standard broker symbol e.g. XAUUSD, EURUSD), entry (number or null), stop_loss (number or null), take_profit (number or null), take_profits (array of numbers), notes (string). Map GOLD to XAUUSD. Extract all TPs into take_profits array. Ignore promotional text, VIP mentions or admin links. If not an actionable trade signal, set is_signal=false."
    },
    {
      "role": "user",
      "content": {{ JSON.stringify($json.raw_message || "") }}
    }
  ]
}
